        "look_how_to_create": "પ્રોજેક્ટ કેવી રીતે બનાવવું, કાર્યો મેનેજ કરવું, સમય પત્રક અહેવાલો જોવું, ચેટમાં પ્રવેશ કરવો, ઉલ્લેખો અને સૂચનાઓ જોવી અને વધુ જુઓ.",
