        "have_brief_tour_project": "પ્રોજેક્ટનો સંક્ષિપ્ત પ્રવાસ કરો?",
        "look_how_to_create_task": "કાર્ય કેવી રીતે બનાવવું, કાર્ય મેનેજ કરવું, સ્થિતિ જૂથ અનુસાર કાર્ય જોવું અને વધુ જુઓ.",
        "look_how_to_create_project": "પ્રોજેક્ટ કેવી રીતે બનાવવું, પ્રોજેક્ટ મેનેજ કરવું, સ્થિતિ જૂથ અનુસાર કાર્ય જોવું અને વધુ જુઓ.",
        "project_creation_description": "પ્રોજેક્ટ્સને સરળતાથી બનાવવામાં, સોંપવામાં અને ટ્રૅક કરવામાં આવી શકે છે, ટીમ સભ્યો માટે જવાબદારીઓની સ્પષ્ટ દૃશ્યતા સાથે. આ વધુ સારી સંસ્થા પ્રોત્સાહિત કરે છે, જેમાં કાર્યક્ષમતા અને ઉત્પાદકતામાં સુધારો થાય છે. નવું પ્રોજેક્ટ શરૂ કરવા માટે અહીં ક્લિક કરો.",
        "enter_project_name": "તમારા પ્રોજેક્ટ માટે સંક્ષિપ્ત નામ દાખલ કરો.",
        "enter_project_key": "તમારા પ્રોજેક્ટ માટે સંક્ષિપ્ત કી દાખલ કરો.",
        "add_project_category": "તમારા પ્રોજેક્ટ માટે કેટેગરી ઉમેરો.",
        "enter_project_duedate": "તમારા પ્રોજેક્ટ માટે મર્યાદિત તારીખ દાખલ કરો.",
        "add_project_lead_assignee": "તમારા પ્રોજેક્ટ માટે લીડ અસાઇનિ ઉમેરો.",
        "create_project_from_template": "આ વિકલ્પ તમને અસ્તિત્વમાં રહેલા ટેમ્પલેટનો ઉપયોગ કરીને નવી પ્રોજેક્ટ ઝડપી રીતે બનાવવા દે છે, જે પૂર્વ-રૂપરેખિત ડેટા અને સેટિંગ્સ સાથે આવે છે, જેથી તમે આ જ પ્રોજેક્ટ ગોઠવણીને સરળતાથી પુનઃપ્રતિકૃતિ કરી શકો.",
        "customize_project_section": "આ વિકલ્પ તમને તમારા પ્રોજેક્ટને સંપૂર્ણ રીતે વૈયક્તિકૃત કરવાની મંજૂરી આપે છે, જેમ કે સ્થિતિઓ, પ્રકારો, એપ્લિકેશનો અને વધુ જેવા વિવિધ ઘટકોને તમારા વિશિષ્ટ જરૂરિયાતો મુજબ ગોઠવીને.",
