        "end_of_project_view_tour_text": "પ્રોજેક્ટ દ્રશ્ય ટૂર પૂર્ણ",
        "search_and_filter_projects_description_text": "અહીં તમારી માપદંડો આધારિત પ્રોજેક્ટ્સ શોધો અને ફિલ્ટર કરો.",
        "enter_search_keywords_text": "ખાસ પ્રોજેક્ટ્સ શોધવા માટે શોધ કીવર્ડ્સ દાખલ કરો.",
        "search_filter_dropdown_description_text": "શોધ ફિલ્ટર સાથે ડ્રોપડાઉન મેનુ ખોલવા માટે આઇકન પર ક્લિક કરો.",
        "toggle_search_options_description_text": "ટાઈપ કરતી વખતે પ્રોજેક્ટ, સ્પ્રિન્ટ અથવા ફોલ્ડર દ્વારા શોધવા માટે વિકલ્પો વચ્ચે ટૉગલ કરો.",
