        "filter_by_favorites_description_text": "તમારા મનપસંદ પ્રોજેક્ટ્સને યાદીના ટોચ પર પ્રાથમિકતા આપવા માટે સ્ટાર આઇકન પર ક્લિક કરો.",
        "project_settings_icon_description_text": "આર્કાઇવ કરેલ અથવા અનઆર્કાઇવ કરેલ પ્રોજેક્ટ વિકલ્પો વચ્ચે સ્વિચ કરવા માટે સેટિંગ્સ આઇકન પર ક્લિક કરો.",
        "view_project_list_description_text": "અહિયાં તમે તમારી પ્રોજેક્ટ્સની યાદી જોઈ શકો છો.",
        "end_of_project_view_tour_description_text": "ટૂર હવે પૂર્ણ થયો છે.",
        "create_assign_prioritize_monitor_projects_text": "સહજતાથી પ્રોજેક્ટ્સ બનાવો, ફાળવો, પ્રાથમિકતા આપો અને મોનિટર કરો. ટીમના સભ્યોએ તેમની કાર્યો સ્પષ્ટપણે જોઈ શકે છે, ગોઠવણીમાં રહી શકે છે અને કાર્યક્ષમતા અને ઉત્પાદનક્ષમતા સુધારી શકે છે. નવો પ્રોજેક્ટ શરૂ કરવા માટે અહીં ક્લિક કરો.",
        "track_users_time_sheet_reports_text": "વપરાશકર્તાઓનો સમય વિવિધ સમય પત્રક રિપોર્ટ્સ જેમ કે વપરાશકર્તા સમય પત્રક, પ્રોજેક્ટ સમય પત્રક, કાર્યભાર સમય પત્રક અને ટ્રેકર સમય પત્રક સાથે અસરકારક રીતે ટ્રેક કરો. સમય પત્રક રિપોર્ટ્સ અન્વેષણ કરવા માટે અહીં ક્લિક કરો.",
        "user_time_sheet_description_text": "વપરાશકર્તા સમય પત્રક તમને તમારા વપરાશકર્તા ભૂમિકા મુજબ દરેક વપરાશકર્તા દ્વારા દાખલ કરેલા કલાકોની મોનીટરીંગ કરવાની મંજૂરી આપે છે.",
        "project_time_sheet_description_text": "તમારા વપરાશકર્તા ભૂમિકા આધારે પ્રોજેક્ટ સમય પત્રકમાં દરેક પ્રોજેક્ટ માટે નોંધાયેલા કલાકોને ટ્રેક કરો.",
        "workload_time_sheet_description_text": "વપરાશકર્તા સમય પત્રકની જેમ, કાર્યભાર સમય પત્રકમાં વપરાશકર્તાના કાર્યભાર, કુલ કલાકો અને અનુમાનિત કલાકોની વિગતો પણ શામેલ છે.",
        "tracker_sheet_description_text": "ટ્રેકર શીટ સમય ટ્રેકર દ્વારા નોંધાયેલ સમય, સ્ક્રીનશૉટ્સ અને કુલ ટ્રેક કરેલ સમય દર્શાવે છે.",
        "view_companies_switch_text": "તમારા સાથે સંકળાયેલી બધી કંપનીઓ જુઓ અને કોઈ એક પસંદ કરીને સરળતાથી કંપનીઓ વચ્ચે સ્વિચ કરો.",
        "engage_team_real_time_text": "ઝડપી નિર્ણય લેવા માટે રિયલ-ટાઇમમાં ટીમના સભ્યો સાથે જોડાઓ. ચેનલ્સ બનાવો અને જોડાણો, અવાજ સંદેશાઓ અને ટેક્સ્ટ દ્વારા માહિતી શેર કરો.",
        "real_time_notifications_text": "પ્રોજેક્ટ અને કાર્યની પ્રવૃત્તિઓ વિશે રિયલ-ટાઇમ સૂચનાઓ સાથે અપડેટ રહો, જેમાં કાર્ય ફાળવણી, સ્થિતિ ફેરફાર, ટિપ્પણીઓ અને સમયમર્યાદા શામેલ છે.",
        "address_specific_individuals_text": "પ્રોજેક્ટ મેનેજમેન્ટ સિસ્ટમમાં વિશિષ્ટ વ્યક્તિઓને સીધા સંબોધન કરો. કાર્યો, પ્રોજેક્ટ્સ અથવા ચર્ચાઓ સાથે સંબંધિત ઉલ્લેખ જુઓ.",
